BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_USER (ID VARCHAR2(36 CHAR) PRIMARY KEY, LOGIN VARCHAR2(128 CHAR) NOT NULL UNIQUE, EMAIL VARCHAR2(320 CHAR) UNIQUE, DISPLAY_NAME VARCHAR2(200 CHAR) NOT NULL, STATUS VARCHAR2(16 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, DELETED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT CK_INX_IAM_USER_STATUS CHECK (STATUS IN (''PENDING'',''ACTIVE'',''SUSPENDED'',''DELETED'')), CONSTRAINT CK_INX_IAM_USER_DELETED CHECK ((STATUS=''DELETED'' AND DELETED_AT IS NOT NULL) OR (STATUS<>''DELETED'' AND DELETED_AT IS NULL)), CONSTRAINT CK_INX_IAM_USER_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_USER_STATUS ON INFRANEXUM_IAM_USER(STATUS,LOGIN)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_USER_MEMBERSHIP (ID VARCHAR2(36 CHAR) PRIMARY KEY, USER_ID VARCHAR2(36 CHAR) NOT NULL, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR), EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, EFFECTIVE_TO TIMESTAMP(6) WITH TIME ZONE, REVOKED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT FK_INX_IAM_MEM_USER FOREIGN KEY(USER_ID) REFERENCES INFRANEXUM_IAM_USER(ID), CONSTRAINT FK_INX_IAM_MEM_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT FK_INX_IAM_MEM_SUB FOREIGN KEY(ORGANIZATION_ID,SUBDIVISION_ID) REFERENCES INFRANEXUM_ORG_SUBDIVISION(ORGANIZATION_ID,ID), CONSTRAINT CK_INX_IAM_MEM_PERIOD CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>EFFECTIVE_FROM), CONSTRAINT CK_INX_IAM_MEM_REVOKE CHECK (REVOKED_AT IS NULL OR REVOKED_AT>=EFFECTIVE_FROM), CONSTRAINT CK_INX_IAM_MEM_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_MEM_EFFECTIVE ON INFRANEXUM_IAM_USER_MEMBERSHIP(USER_ID,ORGANIZATION_ID,SUBDIVISION_ID,EFFECTIVE_FROM,EFFECTIVE_TO,REVOKED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_GROUP (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, CODE VARCHAR2(96 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(200 CHAR) NOT NULL, SYSTEM_GROUP NUMBER(1) DEFAULT 0 NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, DELETED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT UQ_INX_IAM_GROUP_ORG_CODE UNIQUE(ORGANIZATION_ID,CODE), CONSTRAINT UQ_INX_IAM_GROUP_ORG_ID UNIQUE(ORGANIZATION_ID,ID), CONSTRAINT FK_INX_IAM_GROUP_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT CK_INX_IAM_GROUP_SYSTEM CHECK (SYSTEM_GROUP IN (0,1)), CONSTRAINT CK_INX_IAM_GROUP_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
