BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_GROUP_USER_MEMBER (ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, GROUP_ID VARCHAR2(36 CHAR) NOT NULL, USER_ID VARCHAR2(36 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT PK_INX_IAM_GUM PRIMARY KEY(GROUP_ID,USER_ID), CONSTRAINT FK_INX_IAM_GUM_GROUP FOREIGN KEY(ORGANIZATION_ID,GROUP_ID) REFERENCES INFRANEXUM_IAM_GROUP(ORGANIZATION_ID,ID), CONSTRAINT FK_INX_IAM_GUM_USER FOREIGN KEY(USER_ID) REFERENCES INFRANEXUM_IAM_USER(ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_GROUP_GROUP_MEMBER (ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, PARENT_GROUP_ID VARCHAR2(36 CHAR) NOT NULL, CHILD_GROUP_ID VARCHAR2(36 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT PK_INX_IAM_GGM PRIMARY KEY(PARENT_GROUP_ID,CHILD_GROUP_ID), CONSTRAINT FK_INX_IAM_GGM_PARENT FOREIGN KEY(ORGANIZATION_ID,PARENT_GROUP_ID) REFERENCES INFRANEXUM_IAM_GROUP(ORGANIZATION_ID,ID), CONSTRAINT FK_INX_IAM_GGM_CHILD FOREIGN KEY(ORGANIZATION_ID,CHILD_GROUP_ID) REFERENCES INFRANEXUM_IAM_GROUP(ORGANIZATION_ID,ID), CONSTRAINT CK_INX_IAM_GGM_SELF CHECK (PARENT_GROUP_ID<>CHILD_GROUP_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
