BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_PERMISSION (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR), CODE VARCHAR2(160 CHAR) NOT NULL, RESOURCE_TYPE VARCHAR2(64 CHAR) NOT NULL, ACTION_NAME VARCHAR2(64 CHAR) NOT NULL, SENSITIVITY VARCHAR2(16 CHAR) NOT NULL, SCOPE_KIND VARCHAR2(16 CHAR) NOT NULL, SYSTEM_DEFINED NUMBER(1) NOT NULL, ACTIVE NUMBER(1) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, DELETED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT FK_INX_IAM_PERM_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT CK_INX_IAM_PERM_SENS CHECK (SENSITIVITY IN (''NORMAL'',''ELEVATED'',''CRITICAL'')), CONSTRAINT CK_INX_IAM_PERM_SCOPE CHECK (SCOPE_KIND IN (''PLATFORM'',''ORGANIZATION'',''SUBDIVISION'')), CONSTRAINT CK_INX_IAM_PERM_SYS CHECK (SYSTEM_DEFINED IN (0,1) AND ACTIVE IN (0,1)), CONSTRAINT CK_INX_IAM_PERM_OWNER CHECK ((SYSTEM_DEFINED=1 AND ORGANIZATION_ID IS NULL) OR (SYSTEM_DEFINED=0 AND ORGANIZATION_ID IS NOT NULL)), CONSTRAINT CK_INX_IAM_PERM_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX UQ_INX_IAM_PERM_CODE ON INFRANEXUM_IAM_PERMISSION(NVL(ORGANIZATION_ID,''platform''),CODE)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ROLE (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR), CODE VARCHAR2(160 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(200 CHAR) NOT NULL, SCOPE_KIND VARCHAR2(16 CHAR) NOT NULL, SYSTEM_ROLE NUMBER(1) NOT NULL, ACTIVE NUMBER(1) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, DELETED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT FK_INX_IAM_ROLE_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT CK_INX_IAM_ROLE_SCOPE CHECK (SCOPE_KIND IN (''PLATFORM'',''ORGANIZATION'',''SUBDIVISION'')), CONSTRAINT CK_INX_IAM_ROLE_FLAGS CHECK (SYSTEM_ROLE IN (0,1) AND ACTIVE IN (0,1)), CONSTRAINT CK_INX_IAM_ROLE_OWNER CHECK ((SYSTEM_ROLE=1 AND ORGANIZATION_ID IS NULL) OR (SYSTEM_ROLE=0 AND ORGANIZATION_ID IS NOT NULL)), CONSTRAINT CK_INX_IAM_ROLE_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
