BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ROLE_PERMISSION (ROLE_ID VARCHAR2(36 CHAR) NOT NULL, PERMISSION_ID VARCHAR2(36 CHAR) NOT NULL, CONSTRAINT PK_INX_IAM_RP PRIMARY KEY(ROLE_ID,PERMISSION_ID), CONSTRAINT FK_INX_IAM_RP_ROLE FOREIGN KEY(ROLE_ID) REFERENCES INFRANEXUM_IAM_ROLE(ID), CONSTRAINT FK_INX_IAM_RP_PERM FOREIGN KEY(PERMISSION_ID) REFERENCES INFRANEXUM_IAM_PERMISSION(ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_IAM_ROLE_ASSIGNMENT (ID VARCHAR2(36 CHAR) PRIMARY KEY, ROLE_ID VARCHAR2(36 CHAR) NOT NULL, ACTOR_TYPE VARCHAR2(16 CHAR) NOT NULL, ACTOR_ID VARCHAR2(36 CHAR) NOT NULL, SCOPE_KIND VARCHAR2(16 CHAR) NOT NULL, ORGANIZATION_ID VARCHAR2(36 CHAR), SUBDIVISION_ID VARCHAR2(36 CHAR), EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, EFFECTIVE_TO TIMESTAMP(6) WITH TIME ZONE, REVOKED_AT TIMESTAMP(6) WITH TIME ZONE, REVOKED_BY VARCHAR2(36 CHAR), CONSTRAINT FK_INX_IAM_RA_ROLE FOREIGN KEY(ROLE_ID) REFERENCES INFRANEXUM_IAM_ROLE(ID), CONSTRAINT FK_INX_IAM_RA_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT FK_INX_IAM_RA_SUB FOREIGN KEY(ORGANIZATION_ID,SUBDIVISION_ID) REFERENCES INFRANEXUM_ORG_SUBDIVISION(ORGANIZATION_ID,ID), CONSTRAINT FK_INX_IAM_RA_REVOKER FOREIGN KEY(REVOKED_BY) REFERENCES INFRANEXUM_IAM_USER(ID), CONSTRAINT CK_INX_IAM_RA_ACTOR CHECK (ACTOR_TYPE IN (''USER'',''GROUP'')), CONSTRAINT CK_INX_IAM_RA_SCOPE CHECK ((SCOPE_KIND=''PLATFORM'' AND ORGANIZATION_ID IS NULL AND SUBDIVISION_ID IS NULL) OR (SCOPE_KIND=''ORGANIZATION'' AND ORGANIZATION_ID IS NOT NULL AND SUBDIVISION_ID IS NULL) OR (SCOPE_KIND=''SUBDIVISION'' AND ORGANIZATION_ID IS NOT NULL AND SUBDIVISION_ID IS NOT NULL)), CONSTRAINT CK_INX_IAM_RA_PERIOD CHECK (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>EFFECTIVE_FROM), CONSTRAINT CK_INX_IAM_RA_REVOKE CHECK ((REVOKED_AT IS NULL AND REVOKED_BY IS NULL) OR (REVOKED_AT IS NOT NULL AND REVOKED_BY IS NOT NULL AND REVOKED_AT>=EFFECTIVE_FROM)), CONSTRAINT CK_INX_IAM_RA_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_IAM_RA_EFFECTIVE ON INFRANEXUM_IAM_ROLE_ASSIGNMENT(ACTOR_TYPE,ACTOR_ID,EFFECTIVE_FROM,EFFECTIVE_TO,REVOKED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
